<?php require_once 'config/functions.php';require_login();$uid=user_id();$types=['reading'=>['Reading','pages read','📚'],'sleep'=>['Sleep','hours slept','🌙'],'screen_time'=>['Screen Time','hours used','📱'],'savings'=>['Savings','amount saved','💰']];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$type=$_POST['tracker_type'];if(isset($types[$type])){$pdo->prepare('INSERT INTO trackers(user_id,tracker_type,record_date,value,details) VALUES(?,?,?,?,?)')->execute([$uid,$type,$_POST['record_date'],(float)$_POST['value'],trim($_POST['details']??'')]);flash('Tracker record saved.');}redirect('trackers.php');}$q=$pdo->prepare('SELECT * FROM trackers WHERE user_id=? ORDER BY record_date DESC,id DESC LIMIT 40');$q->execute([$uid]);$records=$q->fetchAll();page_header('Life Trackers');?><div class="grid grid-2"><?php foreach($types as $key=>$t):?><div class="card"><h3><?=$t[2]?> <?=$t[0]?></h3><form method="post" class="form"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="tracker_type" value="<?=$key?>"><div class="grid grid-2"><div class="field"><label>Date</label><input type="date" name="record_date" value="<?=date('Y-m-d')?>" required></div><div class="field"><label><?=$t[1]?></label><input type="number" name="value" min="0" step="0.1" required></div></div><div class="field"><label>Details (optional)</label><input name="details" placeholder="Book title, app, note..."></div><button>Save <?=$t[0]?></button></form></div><?php endforeach;?></div><div class="card" style="margin-top:18px"><h3>History</h3><?php if(!$records):?><div class="empty">Tracker records appear here when you start adding them.</div><?php else:?><table class="table"><thead><tr><th>Date</th><th>Tracker</th><th>Value</th><th>Details</th></tr></thead><tbody><?php foreach($records as $r):?><tr><td><?=h($r['record_date'])?></td><td><?=h($types[$r['tracker_type']][0])?></td><td><?=h($r['value'])?></td><td><?=h($r['details'])?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div><?php page_footer();
